var l=[{title:`Два поширені застосування`,text:`RPE заняття оцінює загальну складність усього тренування, часто за шкалою 0–10 у стилі категорійного співвідношення, що йде від спокою до максимального зусилля. RPE підходу оцінює один підхід силового тренування. Вони вимірюють різне: один підхід може бути надзвичайно важким у занятті, яке загалом здалося помірним.`},{title:`RPE підходу та повторення в запасі`,text:`Одна система силових тренувань пов’язує кожну оцінку з кількістю повторень, які, на вашу думку, лишилися. RPE 10 означає, що ви не могли б зробити ще одне повне повторення із задуманою технікою, RPE 9 означає, що лишилося одне, а RPE 8 означає, що лишилося приблизно два. Це оцінки, а не точні фізіологічні вимірювання, і з тренувальним досвідом ви стаєте в них кращими.`},{title:`Приклади`,text:`Жвава 25-хвилинна прогулянка може здаватися 4/10 для однієї людини і 7/10 для нетренованого початківця. Підхід із восьми присідань із ще приблизно двома можливими повтореннями був би приблизно RPE 8 за шкалою повторень у запасі. Завжди кажіть, яку шкалу використовуєте, інакше числа плутають.`},{title:`Поширені помилки`,text:`Оцінки втрачають цінність, якщо оцінювати зусилля лише за тим, скільки ви спітніли, плутати болючість м’язів зі складністю заняття чи завжди обирати 10, бо тренування «має бути важким». Сон, стрес, спека й незнайомі рухи змінюють, наскільки важкими здаються вправи, тож читайте кожну оцінку в її контексті.`},{title:`Перетворення оцінок на рішення`,text:`Якщо кілька занять здаються значно важчими за заплановане, подивіться на сон, вагу, кількість підходів, відпочинок і відновлення. Якщо заняття постійно здаються дуже легкими, а техніка надійна, спробуйте невелике збільшення наступного разу. Однієї незвичної оцінки недостатньо, щоб діагностувати перетренування чи робити великі зміни.`},{title:`Використання TrainUp`,text:`Після кожного тренування ви оцінюєте все заняття від 1 до 10. Сприймайте це число як зусилля заняття й не перетворюйте його на RPE підходу чи повторення в запасі. Дивіться на свої оцінки поряд із тим, яку частину кожного тренування ви завершили, упродовж кількох тренувань.`}];var i=[{label:`Дослідження RPE на основі RIR (Зурдос та співавт.)`,url:`https://pubmed.ncbi.nlm.nih.gov/26049792/`},{label:`Практичні поради щодо RPE (Хелмс та співавт.)`,url:`https://pubmed.ncbi.nlm.nih.gov/27531969/`},{label:`Рекомендації CDC щодо зусилля`,url:`https://www.cdc.gov/physical-activity-basics/measuring/`}];var R={sections:l,sources:i};export{R as default,l as sections,i as sources};